PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE member_specs (
  member_id INTEGER PRIMARY KEY,
  vehicle1_class TEXT
    CHECK (
      vehicle1_class IS NULL
      OR vehicle1_class IN ('fighter','shooter','rider')
    ),
  vehicle1_power_value REAL
    CHECK (
      vehicle1_power_value IS NULL
      OR vehicle1_power_value > 0
    ),
  vehicle1_power_unit TEXT
    CHECK (
      vehicle1_power_unit IS NULL
      OR vehicle1_power_unit IN ('M','G')
    ),
  vehicle1_power_normalized REAL
    CHECK (
      vehicle1_power_normalized IS NULL
      OR vehicle1_power_normalized > 0
    ),
  vehicle2_class TEXT
    CHECK (
      vehicle2_class IS NULL
      OR vehicle2_class IN ('fighter','shooter','rider')
    ),
  vehicle2_power_value REAL
    CHECK (
      vehicle2_power_value IS NULL
      OR vehicle2_power_value > 0
    ),
  vehicle2_power_unit TEXT
    CHECK (
      vehicle2_power_unit IS NULL
      OR vehicle2_power_unit IN ('M','G')
    ),
  vehicle2_power_normalized REAL
    CHECK (
      vehicle2_power_normalized IS NULL
      OR vehicle2_power_normalized > 0
    ),
  season_war_available INTEGER
    CHECK (
      season_war_available IS NULL
      OR season_war_available IN (0,1)
    ),
  bgb_available_hour INTEGER
    CHECK (
      bgb_available_hour IS NULL
      OR bgb_available_hour BETWEEN 0 AND 23
    ),
  discord TEXT
    CHECK (
      discord IS NULL
      OR length(trim(discord)) <= 100
    ),
  telegram TEXT
    CHECK (
      telegram IS NULL
      OR length(trim(telegram)) <= 100
    ),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, profile_specs_registered INTEGER NOT NULL DEFAULT 0 CHECK (profile_specs_registered IN (0,1)), member_self_updated_at TEXT,
  FOREIGN KEY (member_id)
    REFERENCES members(id)
    ON UPDATE CASCADE
    ON DELETE CASCADE
);
CREATE TABLE sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id INTEGER NOT NULL,
  token_hash TEXT NOT NULL UNIQUE
    CHECK (length(token_hash) BETWEEN 32 AND 256),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at TEXT NOT NULL
    CHECK (datetime(expires_at) IS NOT NULL),
  last_used_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    CHECK (datetime(last_used_at) IS NOT NULL),
  user_agent TEXT
    CHECK (
      user_agent IS NULL
      OR length(user_agent) <= 500
    ),
  ip_hash TEXT
    CHECK (
      ip_hash IS NULL
      OR length(ip_hash) <= 256
    ),
  FOREIGN KEY (member_id)
    REFERENCES members(id)
    ON UPDATE CASCADE
    ON DELETE CASCADE
);
CREATE TABLE settings (
  key TEXT PRIMARY KEY
    CHECK (length(trim(key)) BETWEEN 1 AND 100),
  value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_by TEXT
    CHECK (
      updated_by IS NULL
      OR length(trim(updated_by)) BETWEEN 1 AND 100
    )
);
CREATE TABLE member_nickname_history (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id INTEGER NOT NULL,
  old_nickname TEXT NOT NULL
    CHECK (length(trim(old_nickname)) BETWEEN 1 AND 64),
  new_nickname TEXT NOT NULL
    CHECK (length(trim(new_nickname)) BETWEEN 1 AND 64),
  changed_by TEXT NOT NULL
    CHECK (changed_by IN ('member','admin')),
  changed_by_member_id INTEGER,
  changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (member_id)
    REFERENCES members(id)
    ON UPDATE CASCADE
    ON DELETE CASCADE,
  FOREIGN KEY (changed_by_member_id)
    REFERENCES members(id)
    ON UPDATE CASCADE
    ON DELETE SET NULL
);
CREATE TABLE admin_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  admin_member_id INTEGER,
  admin_login_id_snapshot TEXT NOT NULL
    CHECK (
      length(trim(admin_login_id_snapshot)) BETWEEN 1 AND 100
    ),
  action TEXT NOT NULL
    CHECK (
      action IN (
        'member_update',
        'nickname_update',
        'temporary_password_issued',
        'member_activated',
        'member_suspended',
        'member_left',
        'member_deleted',
        'join_code_changed',
        'signup_enabled',
        'signup_disabled',
        'admin_role_granted',
        'admin_role_revoked'
      )
    ),
  target_member_id INTEGER,
  target_login_id_snapshot TEXT,
  target_nickname_snapshot TEXT,
  details TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (admin_member_id)
    REFERENCES members(id)
    ON UPDATE CASCADE
    ON DELETE SET NULL,
  FOREIGN KEY (target_member_id)
    REFERENCES members(id)
    ON UPDATE CASCADE
    ON DELETE SET NULL
);
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE member_admin_memos (
  member_id INTEGER PRIMARY KEY,
  memo TEXT NOT NULL DEFAULT ''
    CHECK (length(memo) <= 1000),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_by_member_id INTEGER,
  FOREIGN KEY (member_id) REFERENCES members(id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  FOREIGN KEY (updated_by_member_id) REFERENCES members(id)
    ON UPDATE CASCADE ON DELETE SET NULL
);
CREATE TABLE member_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id INTEGER,
  author_nickname_snapshot TEXT NOT NULL DEFAULT '',
  title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 120),
  message TEXT NOT NULL CHECK(length(trim(message)) BETWEEN 1 AND 3000),
  admin_answer TEXT,
  answered_at TEXT,
  answered_by_member_id INTEGER,
  is_legacy INTEGER NOT NULL DEFAULT 0 CHECK(is_legacy IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, request_type TEXT NOT NULL DEFAULT 'general', promotion_target_rank TEXT,
  FOREIGN KEY(member_id) REFERENCES members(id) ON UPDATE CASCADE ON DELETE SET NULL,
  FOREIGN KEY(answered_by_member_id) REFERENCES members(id) ON UPDATE CASCADE ON DELETE SET NULL
);
CREATE TABLE votes (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',vote_type TEXT NOT NULL DEFAULT 'single' CHECK(vote_type IN ('single','multiple')),status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','active','ended')),starts_at TEXT,ends_at TEXT,show_results INTEGER NOT NULL DEFAULT 0,created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,ended_at TEXT,FOREIGN KEY(created_by) REFERENCES members(id));
CREATE TABLE vote_options (id INTEGER PRIMARY KEY AUTOINCREMENT,vote_id INTEGER NOT NULL,label TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(vote_id) REFERENCES votes(id) ON DELETE CASCADE);
CREATE TABLE vote_responses (id INTEGER PRIMARY KEY AUTOINCREMENT,vote_id INTEGER NOT NULL,member_id INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(vote_id,member_id),FOREIGN KEY(vote_id) REFERENCES votes(id) ON DELETE CASCADE,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE TABLE vote_response_options (response_id INTEGER NOT NULL,option_id INTEGER NOT NULL,PRIMARY KEY(response_id,option_id),FOREIGN KEY(response_id) REFERENCES vote_responses(id) ON DELETE CASCADE,FOREIGN KEY(option_id) REFERENCES vote_options(id) ON DELETE CASCADE);
CREATE TABLE vote_member_states (member_id INTEGER PRIMARY KEY,consecutive_missed_votes INTEGER NOT NULL DEFAULT 0,last_vote_id INTEGER,last_vote_status TEXT NOT NULL DEFAULT 'none',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE TABLE vote_member_exclusions (member_id INTEGER PRIMARY KEY,excluded INTEGER NOT NULL DEFAULT 1,reason TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE TABLE vote_eligible_members (vote_id INTEGER NOT NULL,member_id INTEGER NOT NULL,PRIMARY KEY(vote_id,member_id),FOREIGN KEY(vote_id) REFERENCES votes(id) ON DELETE CASCADE,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "members" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  login_id TEXT NOT NULL COLLATE NOCASE UNIQUE
    CHECK (
      length(login_id) BETWEEN 4 AND 32
      AND login_id = lower(login_id)
      AND login_id NOT GLOB '*[^a-z0-9._-]*'
      AND substr(login_id, 1, 1) GLOB '[a-z0-9]'
      AND substr(login_id, -1, 1) GLOB '[a-z0-9]'
    ),
  password_hash TEXT NOT NULL CHECK (length(password_hash) BETWEEN 32 AND 512),
  password_salt TEXT NOT NULL CHECK (length(password_salt) BETWEEN 16 AND 256),
  password_algorithm TEXT NOT NULL DEFAULT 'pbkdf2-sha256'
    CHECK (password_algorithm IN ('pbkdf2-sha256')),
  password_iterations INTEGER NOT NULL DEFAULT 10000 CHECK (password_iterations >= 10000),
  nickname TEXT NOT NULL CHECK (length(trim(nickname)) BETWEEN 1 AND 64),
  power INTEGER CHECK (power IS NULL OR power > 0),
  industry_level TEXT CHECK (
    industry_level IS NULL OR industry_level IN (
      'I1','I2','I3','I4','I5','I6','I7','I8','I9','I10'
    )
  ),
  member_rank TEXT NOT NULL CHECK (member_rank IN ('R1','R2','R3','R4','R5')),
  role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('member','admin')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','left')),
  must_change_password INTEGER NOT NULL DEFAULT 0 CHECK (must_change_password IN (0,1)),
  nickname_updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_login_at TEXT,
  password_changed_at TEXT,
  nickname_change_count INTEGER NOT NULL DEFAULT 0 CHECK (nickname_change_count >= 0),
  approval_status TEXT NOT NULL DEFAULT 'approved' CHECK (approval_status IN ('pending','approved','rejected')), admin_level TEXT DEFAULT NULL CHECK (admin_level IS NULL OR admin_level IN ('sub','super')),
  CHECK (last_login_at IS NULL OR datetime(last_login_at) IS NOT NULL),
  CHECK (password_changed_at IS NULL OR datetime(password_changed_at) IS NOT NULL)
);
CREATE TABLE event_schedule_meta (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  last_updated TEXT NOT NULL DEFAULT '',
  timezone TEXT NOT NULL DEFAULT 'UTC-02:00',
  timezone_label TEXT NOT NULL DEFAULT 'ST',
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slot_no INTEGER NOT NULL UNIQUE CHECK (slot_no BETWEEN 1 AND 9),
  title TEXT NOT NULL DEFAULT '',
  starts_at TEXT NOT NULL DEFAULT '',
  ends_at TEXT NOT NULL DEFAULT '',
  enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0,1)),
  important INTEGER NOT NULL DEFAULT 0 CHECK (important IN (0,1)),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE strategy_content (
  content_key TEXT PRIMARY KEY,
  content_json TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE admin_activity_logs (
 id INTEGER PRIMARY KEY AUTOINCREMENT, actor_member_id INTEGER, actor_login_id TEXT, actor_nickname TEXT NOT NULL,
 actor_admin_level TEXT NOT NULL CHECK(actor_admin_level IN ('super','sub')), category TEXT NOT NULL, action TEXT NOT NULL,
 target_type TEXT, target_id TEXT, target_name TEXT, before_data TEXT, after_data TEXT,
 result TEXT NOT NULL DEFAULT 'success' CHECK(result IN ('success','denied','failed')), failure_reason TEXT,
 ip_address TEXT, user_agent TEXT, request_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE admin_menu_permissions (
  member_id INTEGER PRIMARY KEY,
  members INTEGER NOT NULL DEFAULT 1 CHECK (members IN (0,1)),
  events INTEGER NOT NULL DEFAULT 1 CHECK (events IN (0,1)),
  vote INTEGER NOT NULL DEFAULT 1 CHECK (vote IN (0,1)),
  bgb INTEGER NOT NULL DEFAULT 1 CHECK (bgb IN (0,1)),
  capital_war INTEGER NOT NULL DEFAULT 1 CHECK (capital_war IN (0,1)),
  season INTEGER NOT NULL DEFAULT 1 CHECK (season IN (0,1)),
  requests INTEGER NOT NULL DEFAULT 1 CHECK (requests IN (0,1)),
  accounts INTEGER NOT NULL DEFAULT 1 CHECK (accounts IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, alliance_layout INTEGER NOT NULL DEFAULT 1 CHECK (alliance_layout IN (0,1)), migration INTEGER NOT NULL DEFAULT 1 CHECK (migration IN (0,1)),
  FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE
);
CREATE TABLE strategy_content_history (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  content_key TEXT NOT NULL,
  content_json TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE alliance_layout_versions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  layout_type TEXT NOT NULL CHECK (layout_type IN ('draft','published')),
  direction TEXT NOT NULL CHECK (direction IN ('top','bottom','left','right')),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
  target_count INTEGER NOT NULL DEFAULT 0 CHECK (target_count >= 0),
  placed_count INTEGER NOT NULL DEFAULT 0 CHECK (placed_count >= 0),
  unplaced_count INTEGER NOT NULL DEFAULT 0 CHECK (unplaced_count >= 0),
  missing_specs_count INTEGER NOT NULL DEFAULT 0 CHECK (missing_specs_count >= 0),
  created_by_member_id INTEGER,
  updated_by_member_id INTEGER,
  published_by_member_id INTEGER,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  published_at TEXT,
  FOREIGN KEY (created_by_member_id) REFERENCES members(id) ON DELETE SET NULL,
  FOREIGN KEY (updated_by_member_id) REFERENCES members(id) ON DELETE SET NULL,
  FOREIGN KEY (published_by_member_id) REFERENCES members(id) ON DELETE SET NULL
);
CREATE TABLE alliance_layout_positions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  layout_version_id INTEGER NOT NULL,
  member_id INTEGER NOT NULL,
  placement_rank INTEGER NOT NULL CHECK (placement_rank BETWEEN 1 AND 100),
  grid_row INTEGER NOT NULL CHECK (grid_row BETWEEN 0 AND 9),
  grid_col INTEGER NOT NULL CHECK (grid_col BETWEEN 0 AND 10),
  is_locked INTEGER NOT NULL DEFAULT 0 CHECK (is_locked IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (layout_version_id) REFERENCES alliance_layout_versions(id) ON DELETE CASCADE,
  FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE,
  UNIQUE(layout_version_id,member_id),
  UNIQUE(layout_version_id,placement_rank),
  UNIQUE(layout_version_id,grid_row,grid_col)
);
CREATE TABLE member_daily_visits (
  member_id INTEGER NOT NULL,
  visit_date TEXT NOT NULL,
  first_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(member_id,visit_date),
  FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE
);
CREATE TABLE member_activity_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id INTEGER NOT NULL,
  activity_type TEXT NOT NULL CHECK(activity_type IN ('specs_update')),
  source TEXT NOT NULL DEFAULT 'member' CHECK(source IN ('member','admin')),
  changed_fields TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE
);
CREATE TABLE member_activity_confirmations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id INTEGER NOT NULL,
  confirmed_by_member_id INTEGER NOT NULL,
  checked_login INTEGER NOT NULL DEFAULT 0 CHECK(checked_login IN (0,1)),
  checked_event INTEGER NOT NULL DEFAULT 0 CHECK(checked_event IN (0,1)),
  checked_alliance INTEGER NOT NULL DEFAULT 0 CHECK(checked_alliance IN (0,1)),
  memo TEXT NOT NULL DEFAULT '',
  confirmed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  revoked_at TEXT,
  revoked_by_member_id INTEGER,
  FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE,
  FOREIGN KEY(confirmed_by_member_id) REFERENCES members(id),
  FOREIGN KEY(revoked_by_member_id) REFERENCES members(id)
);
CREATE TABLE member_rank_changes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id INTEGER NOT NULL,
  change_type TEXT NOT NULL CHECK(change_type IN ('promotion','demotion','manual','restoration')),
  from_rank TEXT NOT NULL,
  to_rank TEXT NOT NULL,
  reason TEXT NOT NULL DEFAULT '',
  activity_snapshot TEXT,
  changed_by_member_id INTEGER NOT NULL,
  protection_until TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, dismissed_at TEXT,
  FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE,
  FOREIGN KEY(changed_by_member_id) REFERENCES members(id)
);
CREATE TABLE member_demotion_exclusions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id INTEGER NOT NULL,
  excluded_until TEXT NOT NULL,
  reason TEXT NOT NULL,
  created_by_member_id INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  revoked_at TEXT,
  revoked_by_member_id INTEGER,
  FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE,
  FOREIGN KEY(created_by_member_id) REFERENCES members(id),
  FOREIGN KEY(revoked_by_member_id) REFERENCES members(id)
);
CREATE TABLE migration_applications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  player_name TEXT NOT NULL CHECK (length(trim(player_name)) BETWEEN 1 AND 64),
  game_uid TEXT NOT NULL CHECK (length(game_uid) = 16 AND game_uid NOT GLOB '*[^0-9]*'),
  discord TEXT CHECK (discord IS NULL OR length(trim(discord)) <= 100),
  current_state TEXT NOT NULL CHECK (length(current_state) BETWEEN 1 AND 9 AND current_state NOT GLOB '*[^0-9]*'),
  current_alliance TEXT CHECK (current_alliance IS NULL OR length(trim(current_alliance)) <= 64),

  vehicle1_power_value REAL NOT NULL CHECK (vehicle1_power_value > 0),
  vehicle1_power_unit TEXT NOT NULL CHECK (vehicle1_power_unit IN ('M','G')),
  vehicle1_power_normalized REAL NOT NULL CHECK (vehicle1_power_normalized > 0),
  vehicle2_power_value REAL CHECK (vehicle2_power_value IS NULL OR vehicle2_power_value > 0),
  vehicle2_power_unit TEXT CHECK (vehicle2_power_unit IS NULL OR vehicle2_power_unit IN ('M','G')),
  vehicle2_power_normalized REAL CHECK (vehicle2_power_normalized IS NULL OR vehicle2_power_normalized > 0),
  industry_level INTEGER NOT NULL CHECK (industry_level BETWEEN 1 AND 10),
  spending_level INTEGER NOT NULL CHECK (spending_level BETWEEN 1 AND 10),
  migration_tier TEXT NOT NULL CHECK (migration_tier IN ('gray','blue','purple','gold')),

  migration_reason TEXT NOT NULL CHECK (length(trim(migration_reason)) BETWEEN 1 AND 2000),
  additional_notes TEXT CHECK (additional_notes IS NULL OR length(trim(additional_notes)) <= 2000),
  migration_group TEXT CHECK (migration_group IS NULL OR length(trim(migration_group)) <= 200),
  referrer TEXT CHECK (referrer IS NULL OR length(trim(referrer)) <= 64),

  application_status TEXT NOT NULL DEFAULT 'received'
    CHECK (application_status IN ('received','reviewing','approved','rejected')),
  contact_status TEXT NOT NULL DEFAULT 'not_contacted'
    CHECK (contact_status IN ('not_contacted','contacted')),
  admin_memo TEXT CHECK (admin_memo IS NULL OR length(admin_memo) <= 2000),
  rejection_reason TEXT CHECK (rejection_reason IS NULL OR length(trim(rejection_reason)) <= 2000),

  deleted_at TEXT,
  deleted_by_member_id INTEGER,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, source TEXT NOT NULL DEFAULT 'public_form'
  CHECK (source IN ('public_form','admin_excel_import')), import_batch_id INTEGER REFERENCES migration_import_batches(id) ON DELETE SET NULL,

  CHECK ((vehicle2_power_value IS NULL AND vehicle2_power_unit IS NULL AND vehicle2_power_normalized IS NULL)
      OR (vehicle2_power_value IS NOT NULL AND vehicle2_power_unit IS NOT NULL AND vehicle2_power_normalized IS NOT NULL)),
  FOREIGN KEY (deleted_by_member_id) REFERENCES members(id) ON DELETE SET NULL
);
CREATE TABLE migration_tier_settings (
  tier_key TEXT PRIMARY KEY CHECK (tier_key IN ('gray','blue','purple','gold')),
  sort_order INTEGER NOT NULL,
  label_ko TEXT NOT NULL,
  label_en TEXT NOT NULL,
  min_power_normalized REAL,
  max_power_normalized REAL,
  power_range_visible INTEGER NOT NULL DEFAULT 0 CHECK (power_range_visible IN (0,1)),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE migration_rate_limits (
  key_hash TEXT PRIMARY KEY,
  window_started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  request_count INTEGER NOT NULL DEFAULT 1 CHECK (request_count >= 0),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE migration_import_batches (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  idempotency_key TEXT NOT NULL UNIQUE,
  template_version TEXT NOT NULL,
  original_file_name TEXT NOT NULL,
  file_sha256 TEXT NOT NULL,
  actor_member_id INTEGER NOT NULL,
  actor_nickname TEXT NOT NULL,
  total_rows INTEGER NOT NULL DEFAULT 0 CHECK (total_rows >= 0),
  ready_rows INTEGER NOT NULL DEFAULT 0 CHECK (ready_rows >= 0),
  imported_rows INTEGER NOT NULL DEFAULT 0 CHECK (imported_rows >= 0),
  skipped_rows INTEGER NOT NULL DEFAULT 0 CHECK (skipped_rows >= 0),
  failed_rows INTEGER NOT NULL DEFAULT 0 CHECK (failed_rows >= 0),
  status TEXT NOT NULL DEFAULT 'processing' CHECK (status IN ('processing','committed','partial','failed')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  committed_at TEXT,
  FOREIGN KEY (actor_member_id) REFERENCES members(id) ON DELETE RESTRICT
);
CREATE TABLE migration_inquiry_sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  application_id INTEGER NOT NULL,
  token_hash TEXT NOT NULL UNIQUE CHECK(length(token_hash) BETWEEN 32 AND 256),
  uid_hash TEXT NOT NULL CHECK(length(uid_hash) BETWEEN 32 AND 256),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_used_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at TEXT NOT NULL CHECK(datetime(expires_at) IS NOT NULL),
  user_agent TEXT CHECK(user_agent IS NULL OR length(user_agent) <= 500),
  FOREIGN KEY(application_id) REFERENCES migration_applications(id) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE TABLE migration_inquiries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  public_id TEXT NOT NULL UNIQUE CHECK(length(public_id) BETWEEN 24 AND 80),
  application_id INTEGER NOT NULL,
  requester_name_snapshot TEXT NOT NULL CHECK(length(trim(requester_name_snapshot)) BETWEEN 1 AND 64),
  title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 120),
  message TEXT NOT NULL CHECK(length(trim(message)) BETWEEN 1 AND 3000),
  status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','answered','closed')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  closed_at TEXT, deleted_at TEXT, deleted_by_member_id INTEGER,
  FOREIGN KEY(application_id) REFERENCES migration_applications(id) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE TABLE migration_inquiry_replies (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  inquiry_id INTEGER NOT NULL,
  author_type TEXT NOT NULL CHECK(author_type IN ('applicant','admin')),
  admin_member_id INTEGER,
  author_nickname_snapshot TEXT NOT NULL CHECK(length(trim(author_nickname_snapshot)) BETWEEN 1 AND 64),
  message TEXT NOT NULL CHECK(length(trim(message)) BETWEEN 1 AND 5000),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(inquiry_id) REFERENCES migration_inquiries(id) ON UPDATE CASCADE ON DELETE CASCADE,
  FOREIGN KEY(admin_member_id) REFERENCES members(id) ON UPDATE CASCADE ON DELETE SET NULL
);
CREATE TABLE member_rank_review_states (
  member_id INTEGER PRIMARY KEY,
  rank_snapshot TEXT NOT NULL,
  promotion_target_rank TEXT,
  spec_qualified_at TEXT,
  promotion_cycle_started_on TEXT,
  promotion_activity_qualified_at TEXT,
  promotion_status TEXT CHECK(promotion_status IN ('IN_PROGRESS','REVIEWABLE','HOLD','WAIT_MAINTENANCE')),
  promotion_hold_started_at TEXT,
  promotion_rule_fingerprint TEXT,
  maintenance_cycle_started_on TEXT,
  maintenance_status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(maintenance_status IN ('ACTIVE','REVIEWABLE')),
  maintenance_reviewable_at TEXT,
  maintenance_last_completed_on TEXT,
  maintenance_verified_at TEXT,
  new_member_protection_until TEXT,
  promotion_unlock_after_maintenance INTEGER NOT NULL DEFAULT 0 CHECK(promotion_unlock_after_maintenance IN (0,1)),
  last_evaluated_at TEXT,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, promotion_reentry_required INTEGER NOT NULL DEFAULT 0
  CHECK(promotion_reentry_required IN (0,1)), promotion_reentry_started_on TEXT,
  FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE
);
CREATE TABLE member_rank_spec_qualifications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id INTEGER NOT NULL,
  target_rank TEXT NOT NULL CHECK(target_rank IN ('R2','R3')),
  qualified_at TEXT NOT NULL,
  rule_snapshot TEXT NOT NULL,
  spec_snapshot TEXT NOT NULL,
  qualification_source TEXT NOT NULL CHECK(qualification_source IN (
    'LEGACY_V435_PERSISTED',
    'BASELINE_CURRENT_SPEC',
    'LIVE_SPEC_QUALIFICATION',
    'RESTORE'
  )),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  
  
  UNIQUE(member_id,target_rank)
);
CREATE TABLE member_rank_history_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  event_key TEXT NOT NULL UNIQUE,
  legacy_change_id INTEGER UNIQUE,
  member_id INTEGER NOT NULL,
  member_login_id_snapshot TEXT,
  member_nickname_snapshot TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK(event_type IN (
    'PROMOTION','DEMOTION','MANUAL_ADJUSTMENT','CORRECTION','RESTORE'
  )),
  from_rank TEXT NOT NULL,
  to_rank TEXT NOT NULL,
  reason_code TEXT NOT NULL,
  public_note TEXT,
  internal_note TEXT,
  decision_source TEXT NOT NULL,
  rule_snapshot TEXT,
  spec_snapshot TEXT,
  cycle_snapshot TEXT,
  public_activity_snapshot TEXT,
  private_audit_snapshot TEXT,
  changed_by_member_id INTEGER,
  changed_by_nickname_snapshot TEXT,
  snapshot_quality TEXT NOT NULL DEFAULT 'FULL' CHECK(snapshot_quality IN ('FULL','LEGACY_PARTIAL')),
  dismissed_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
