CREATE TRIGGER trg_member_specs_updated_at
AFTER UPDATE ON member_specs
FOR EACH ROW
WHEN NEW.updated_at = OLD.updated_at
BEGIN
  UPDATE member_specs
  SET updated_at = CURRENT_TIMESTAMP
  WHERE member_id = NEW.member_id;
END;
CREATE TRIGGER trg_settings_updated_at
AFTER UPDATE ON settings
FOR EACH ROW
WHEN NEW.updated_at = OLD.updated_at
BEGIN
  UPDATE settings
  SET updated_at = CURRENT_TIMESTAMP
  WHERE key = NEW.key;
END;
CREATE TRIGGER trg_specs_normalize_after_insert
AFTER INSERT ON member_specs
FOR EACH ROW
BEGIN
  UPDATE member_specs
  SET
    vehicle1_power_normalized =
      CASE
        WHEN NEW.vehicle1_power_value IS NULL
          OR NEW.vehicle1_power_unit IS NULL
        THEN NULL
        WHEN NEW.vehicle1_power_unit = 'G'
        THEN NEW.vehicle1_power_value * 1000.0
        ELSE NEW.vehicle1_power_value
      END,
    vehicle2_power_normalized =
      CASE
        WHEN NEW.vehicle2_power_value IS NULL
          OR NEW.vehicle2_power_unit IS NULL
        THEN NULL
        WHEN NEW.vehicle2_power_unit = 'G'
        THEN NEW.vehicle2_power_value * 1000.0
        ELSE NEW.vehicle2_power_value
      END
  WHERE member_id = NEW.member_id;
END;
CREATE TRIGGER trg_specs_normalize_after_update
AFTER UPDATE OF
  vehicle1_power_value,
  vehicle1_power_unit,
  vehicle2_power_value,
  vehicle2_power_unit
ON member_specs
FOR EACH ROW
BEGIN
  UPDATE member_specs
  SET
    vehicle1_power_normalized =
      CASE
        WHEN NEW.vehicle1_power_value IS NULL
          OR NEW.vehicle1_power_unit IS NULL
        THEN NULL
        WHEN NEW.vehicle1_power_unit = 'G'
        THEN NEW.vehicle1_power_value * 1000.0
        ELSE NEW.vehicle1_power_value
      END,
    vehicle2_power_normalized =
      CASE
        WHEN NEW.vehicle2_power_value IS NULL
          OR NEW.vehicle2_power_unit IS NULL
        THEN NULL
        WHEN NEW.vehicle2_power_unit = 'G'
        THEN NEW.vehicle2_power_value * 1000.0
        ELSE NEW.vehicle2_power_value
      END
  WHERE member_id = NEW.member_id;
END;
CREATE TRIGGER trg_members_updated_at
AFTER UPDATE ON members
FOR EACH ROW
WHEN NEW.updated_at = OLD.updated_at
BEGIN
  UPDATE members SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;
END;
CREATE TRIGGER trg_migration_applications_uid_unique_insert
BEFORE INSERT ON migration_applications
WHEN NEW.deleted_at IS NULL
 AND EXISTS (
   SELECT 1 FROM migration_applications
   WHERE game_uid = NEW.game_uid
     AND deleted_at IS NULL
 )
BEGIN
  SELECT RAISE(ABORT, 'MIGRATION_APPLICATION_EXISTS');
END;
CREATE TRIGGER trg_migration_applications_uid_unique_update
BEFORE UPDATE OF game_uid, deleted_at ON migration_applications
WHEN NEW.deleted_at IS NULL
 AND EXISTS (
   SELECT 1 FROM migration_applications
   WHERE game_uid = NEW.game_uid
     AND deleted_at IS NULL
     AND id <> OLD.id
 )
BEGIN
  SELECT RAISE(ABORT, 'MIGRATION_APPLICATION_EXISTS');
END;
CREATE VIEW public_members AS
SELECT
  m.id, m.nickname, m.power, m.industry_level, m.member_rank,
  m.created_at AS joined_at, m.updated_at AS basic_updated_at,
  s.vehicle1_class, s.vehicle1_power_value, s.vehicle1_power_unit, s.vehicle1_power_normalized,
  s.vehicle2_class, s.vehicle2_power_value, s.vehicle2_power_unit, s.vehicle2_power_normalized,
  s.season_war_available, s.bgb_available_hour, s.updated_at AS spec_updated_at,
  CASE WHEN
    s.vehicle1_class IS NOT NULL AND s.vehicle1_power_value IS NOT NULL AND s.vehicle1_power_unit IS NOT NULL
    AND s.vehicle2_class IS NOT NULL AND s.vehicle2_power_value IS NOT NULL AND s.vehicle2_power_unit IS NOT NULL
    AND s.season_war_available IS NOT NULL AND s.bgb_available_hour IS NOT NULL
  THEN 1 ELSE 0 END AS spec_completed
FROM members m
LEFT JOIN member_specs s ON s.member_id = m.id
WHERE m.status = 'active';
CREATE VIEW admin_member_overview AS
SELECT
  m.id, m.login_id, m.nickname, m.power, m.industry_level, m.member_rank,
  m.role, m.status, m.approval_status, m.must_change_password,
  m.nickname_change_count, m.nickname_updated_at, m.created_at, m.updated_at,
  m.last_login_at, m.password_changed_at,
  s.vehicle1_class, s.vehicle1_power_value, s.vehicle1_power_unit, s.vehicle1_power_normalized,
  s.vehicle2_class, s.vehicle2_power_value, s.vehicle2_power_unit, s.vehicle2_power_normalized,
  s.season_war_available, s.bgb_available_hour, s.discord, s.telegram,
  s.created_at AS spec_created_at, s.updated_at AS spec_updated_at,
  CASE WHEN
    s.vehicle1_class IS NOT NULL AND s.vehicle1_power_value IS NOT NULL AND s.vehicle1_power_unit IS NOT NULL
    AND s.vehicle2_class IS NOT NULL AND s.vehicle2_power_value IS NOT NULL AND s.vehicle2_power_unit IS NOT NULL
    AND s.season_war_available IS NOT NULL AND s.bgb_available_hour IS NOT NULL
  THEN 1 ELSE 0 END AS spec_completed
FROM members m
LEFT JOIN member_specs s ON s.member_id = m.id;
